    oheng_str = f"목:{counts['목']} 화:{counts['화']} 토:{counts['토']} 금:{counts['금']} 수:{counts['수']}"



    ilju_lower_group = get_group_ss(get_ss(ds, db))

    

    dw_fact_str = "대운 정보 없음"

