def get_color(c):

    c = _to_hanja(c)

    if c in "甲乙寅卯": return "목"

    if c in "丙丁巳午": return "화"

    if c in "戊己辰戌丑未": return "토"

    if c in "庚辛申酉": return "금"

    if c in "壬癸亥子": return "수"

    return "무"



