def get_jijanggan_pure(ji):

    """

    지지의 지장간을 HTML 태그 없이 순수 한자 텍스트(예: '癸·辛·己')로 반환

    (app.py의 saju_fact_summary 팩트 바인딩 전용)

    """

    ji = _to_hanja(ji)

    if ji in ["?", "-", " "]: return "-"

    raw = JIJANGGAN.get(ji, ['-','-','-'])

    clean_list = [j for j in raw if j != '-']

    return "·".join(clean_list) if clean_list else "-"





